package ro.leo.visual;
import android.content.*;import android.os.*;import android.provider.Settings;import android.widget.*;import java.util.*;
/** Real battery broadcasts and Android saver; no fabricated remaining-time estimate. */
public final class BatterySettingsActivity extends LeoActivity {
    private boolean charging;private int selected;private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){show();}};
    protected void onResume(){super.onResume();IntentFilter f=new IntentFilter(Intent.ACTION_BATTERY_CHANGED);f.addAction(PowerManager.ACTION_POWER_SAVE_MODE_CHANGED);registerReceiver(updates,f);show();}
    protected void onPause(){unregisterReceiver(updates);super.onPause();}
    private void show(){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(b!=null)BatterySession.observe(this,b);int level=b==null?0:b.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100/Math.max(1,b.getIntExtra(BatteryManager.EXTRA_SCALE,100));charging=b!=null&&b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)!=0;PowerManager power=(PowerManager)getSystemService(POWER_SERVICE);String health=b==null?"Indisponibil":health(b.getIntExtra(BatteryManager.EXTRA_HEALTH,0));list("Baterie Leo",Arrays.asList("Nivel · "+level+"% · "+(charging?"Încărcare":"Pe baterie"),"Economisire · "+(power.isPowerSaveMode()?"Pornită":"Oprită")+(charging?" · la încărcător":""),"Temperatură · "+(b==null?"—":b.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f+" °C"),"Tensiune · "+(b==null?"—":b.getIntExtra(BatteryManager.EXTRA_VOLTAGE,0)+" mV"),"Stare raportată · "+health,"Ecran și temporizare","Diagnostic complet",BatterySession.text(this)),selected,new Choice(){public void pick(int i){selected=i;if(i==1){options("Economisire Android",new String[]{"Oprită",charging?"Pornire · necesită deconectarea încărcătorului":"Pornită"},new Choice(){public void pick(int n){if(n==1&&charging){notice("Economisirea se poate activa după deconectarea încărcătorului");return;}try{Settings.Global.putInt(getContentResolver(),"low_power",n);show();}catch(RuntimeException e){notice("Comutator indisponibil");}}});}else if(i==5)startActivity(new Intent(BatterySettingsActivity.this,DisplaySettingsActivity.class));else if(i==6)startActivity(new Intent(BatterySettingsActivity.this,DiagnosticActivity.class));else if(i==7)options("Probă de consum",new String[]{BatterySession.active(BatterySettingsActivity.this)?"Încheie și salvează":"Începe pe baterie","Cum măsor?"},new Choice(){public void pick(int action){if(action==1){notice("Scoate USB, începe proba, apoi stinge ecranul cel puțin 5 minute. Încheie înainte să reconectezi cablul. Valorile sunt aproximative.");return;}try{if(BatterySession.active(BatterySettingsActivity.this))BatterySession.stop(BatterySettingsActivity.this);else BatterySession.start(BatterySettingsActivity.this);show();}catch(IllegalStateException e){notice(e.getMessage());}}});else notice("Valoare raportată de driver; fără estimare inventată de autonomie.");}},"Actualiz.",new Runnable(){public void run(){show();}});}
    private static String health(int value){switch(value){case BatteryManager.BATTERY_HEALTH_GOOD:return "Bună";case BatteryManager.BATTERY_HEALTH_OVERHEAT:return "Supraîncălzire";case BatteryManager.BATTERY_HEALTH_COLD:return "Rece";case BatteryManager.BATTERY_HEALTH_DEAD:return "Defectă";case BatteryManager.BATTERY_HEALTH_OVER_VOLTAGE:return "Tensiune mare";default:return "Necunoscută";}}
}
